    holiday_set = set()
    for h in holidays:
        try:
            holiday_set.add(date.fromisoformat(h))
        except ValueError:
            raise ValueError("Invalid holiday date string")

    count = 0
    current = start_date
    while current < end_date:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += timedelta(days=1)

    return count
